import { chapter } from "./resource-chapter";

type PhpUnit = [string,string,string,string,string,string,string,string,string,string,string,string];

function phpChapter(section: string, rows: PhpUnit[]) {
  return chapter(section, rows.map(([id,title,summary,detail,a,b,c,question,answer,wrongA,wrongB,why]) => ({
    id,title,summary,content:[detail,"Run PHP examples on a local development server with sample data. Validate input on the server, encode output for its destination, and keep credentials and private files outside public source folders."],
    level:"Beginner" as const,
    examples:[a,b,c].map((code,index)=>({title:`Example ${index+1}`,code,result:"Run the snippet with a small input and inspect the output or resulting value."})),
    quizzes:[
      {question,options:[answer,wrongA,wrongB],answer:0,explanation:why},
      {question:`Which statement about ${title} is correct?`,options:[answer,wrongB,wrongA],answer:0,explanation:why},
      {question:`When using ${title}, what should you keep in mind?`,options:[answer,wrongA,wrongB],answer:0,explanation:why},
    ],
  })));
}

export const phpLessons = [
  ...phpChapter("PHP Foundations", [
    ["php-intro","What PHP Does","Learn how PHP runs on a server to build dynamic web responses.","PHP is a server-side language. A web server runs PHP code and sends the resulting response, commonly HTML or JSON, to a browser; the browser does not receive the PHP source itself.","<?php echo 'Hello from PHP';","<?php $year = date('Y'); echo $year;","<?php header('Content-Type: application/json'); echo json_encode(['ok' => true]);","Where does PHP normally execute in a web request?","On the server","Only inside the browser","Inside a CSS stylesheet","The server executes PHP and sends the generated response."],
    ["php-install","Installing PHP Locally","Set up a local runtime and confirm PHP commands work.","Use a current PHP runtime and a local web server or development bundle. Keep the local runtime close to the version used in deployment and check enabled extensions for database or XML work.","php -v","php -m","php -S localhost:8000","What does php -v show?","The installed PHP version","A list of database rows","The current HTML page","Version output confirms which PHP runtime is active."],
    ["php-syntax","PHP Tags and Basic Syntax","Write PHP statements and control where code is interpreted.","PHP code is placed inside PHP tags in a PHP file. Statements usually end in semicolons; when a file contains only PHP, omitting the closing tag avoids accidental trailing whitespace output.","<?php\n$message = 'Ready';\necho $message;","<?php\nif (true) { echo 'yes'; }","<?php\nfunction total(int $a, int $b): int { return $a + $b; }","Which character commonly ends a PHP statement?","A semicolon","A comma","A slash","Semicolons terminate PHP statements."],
    ["php-comments","Writing Comments","Add notes that explain intent without changing program behavior.","PHP supports line comments and block comments. Explain why a decision exists rather than repeating what the code already says; remove stale comments when behavior changes.","// one-line note","# another line note","/* A multi-line\n   explanation */","Do PHP comments run as code?","No, comments are ignored by the PHP interpreter","Yes, comments execute after HTML","Only comments in functions run","Comments are for people reading the source."],
    ["php-variables","Variables and Scope","Store values and understand where names are available.","Variable names begin with $. PHP variables are case-sensitive, and scope determines where a variable can be read; pass data explicitly to functions when possible.","$name = 'Mina';","$count = 3; $count += 1;","function greeting(string $name): string { return \"Hi $name\"; }","What begins a PHP variable name?","$","@","#","PHP variables use a dollar sign prefix."],
    ["php-echo-print","Displaying Output with echo and print","Send text into the response generated by PHP.","echo and print can output strings. When values contain user data, escape them for the output context instead of inserting raw input into HTML.","echo 'Welcome';","print 2 + 3;","echo htmlspecialchars($name, ENT_QUOTES, 'UTF-8');","Which is a safe way to place untrusted text in HTML?","Escape it with htmlspecialchars","Concatenate it without checking","Wrap it in a PHP comment","HTML escaping prevents text from being treated as markup."],
    ["php-data-types","PHP Data Types","Recognize scalar, compound, and special values.","PHP values include integers, floats, strings, booleans, arrays, objects, null, and resources. Use types that match the data's meaning and strict comparisons when exact matches matter.","$age = 16;","$price = 19.95;","$profile = ['name' => 'Mina', 'active' => true];","What value represents the absence of a value?","null","false only","An empty array only","null explicitly represents no value."],
    ["php-strings","Working with Strings","Build and inspect text values without confusing data and code.","PHP strings can use single or double quotes, with different interpolation behavior. Use dedicated functions for transformations and encode output when placing text into HTML, URLs, or SQL parameters.","$first = 'Mina';","$message = \"Hello, $first\";","$slug = strtolower(trim('  PHP Basics  '));","Which quote style interpolates variables directly?","Double quotes","Single quotes in all cases","Backticks","Double-quoted PHP strings can interpolate variables."],
    ["php-numbers","Working with Numbers","Choose numeric operations and avoid accidental string conversions.","Integers and floating-point numbers behave differently; decimal fractions may not be represented exactly in binary floating point. For money, store integer minor units or use a decimal-capable database type.","$sum = 12 + 8;","$ratio = 7 / 2;","$cents = 1299; $dollars = $cents / 100;","Why can floating point be awkward for money?","Some decimal fractions are not represented exactly","It cannot store positive numbers","It turns all values into strings","Binary floating-point precision can create rounding surprises."],
    ["php-casting","Converting Values with Casting","Convert a value deliberately and validate external input.","A cast changes a value's type but does not prove that the original input is valid. Validate request data before using it for IDs, amounts, or permissions.","$count = (int) '12';","$enabled = (bool) 1;","$label = (string) 42;","Does casting validate that user input is acceptable?","No, validate it separately","Yes, every cast rejects invalid input","Only string casts validate","Casting converts representation, while validation checks rules."],
    ["php-math","Common Math Operations","Use arithmetic functions and handle ranges deliberately.","PHP includes arithmetic operators and math functions such as abs, round, min, and max. Check input ranges before calculations and choose a suitable numeric representation for the domain.","$total = 4 * 12;","$rounded = round(8.276, 2);","$distance = abs(-9);","What does abs(-9) return?","9","-9","0","abs returns a non-negative magnitude."],
    ["php-constants","Defining Constants","Name values that should not be reassigned during execution.","Constants are created with const or define and are available without the dollar-sign variable syntax. Use descriptive names and avoid placing secret values directly in source control.","const TAX_RATE = 0.08;","define('APP_NAME', 'Study Hub');","echo APP_NAME;","How is a constant referenced?","By its name without a dollar sign","With two dollar signs","Only through $_GET","Constants are referenced by name."],
    ["php-magic-constants","Using Magic Constants","Read special values supplied by PHP for the current code location.","Magic constants such as __FILE__, __DIR__, __LINE__, and __FUNCTION__ are evaluated based on where they appear. They are useful for paths and diagnostics, but avoid exposing filesystem paths to users.","echo __DIR__;","echo __FILE__;","function whereAmI(): string { return __FUNCTION__; }","What does __DIR__ provide?","The directory containing the current file","The current database name","The browser's URL fragment","__DIR__ is the current script file's directory."],
    ["php-operators","PHP Operators","Combine assignment, comparison, arithmetic, and logical expressions.","Operators compute or compare values. Use === and !== when type and value should both match; parentheses make complex boolean expressions easier to review.","$next = $count + 1;","$same = ($left === $right);","$allowed = $isMember && $isActive;","What does === check?","Value and type equality","Only whether values are truthy","Whether two strings are concatenated","Strict equality does not coerce types."],
    ["php-if-else","Making Decisions with if and else","Run different code paths based on a condition.","if and elseif test conditions in order, and else handles the remaining case. Use braces and clear comparisons so each path is easy to understand.","if ($score >= 50) { echo 'Pass'; }","if ($count > 0) { echo 'Many'; } else { echo 'None'; }","if ($role === 'admin') { echo 'Manage'; } elseif ($role === 'editor') { echo 'Edit'; } else { echo 'Read'; }","When does an else block run?","When no preceding condition matched","Every time before if","Only after a loop","else is the fallback branch."],
    ["php-switch","Selecting a Branch with switch","Match one expression against several known cases.","switch is useful when one value maps to multiple branches. Use break to avoid continuing into the next case, or use match where expression semantics are more suitable.","switch ($day) { case 'Mon': echo 'Start'; break; default: echo 'Other'; }","switch ($status) { case 200: $label='OK'; break; case 404: $label='Missing'; break; default: $label='Other'; }","switch ($kind) { case 'book': echo 'Read'; break; case 'video': echo 'Watch'; break; }","What does break prevent in a switch?","Execution from falling through to later cases","A new variable being created","PHP from rendering HTML","break exits the current switch case flow."],
    ["php-match","Using the match Expression","Return a value from an exact-match branch.","match is an expression with strict comparison and no fall-through. Every possible input should be handled or a default arm supplied; unmatched values without default raise an error.","$label = match ($code) { 200 => 'OK', 404 => 'Missing', default => 'Other' };","$size = match ($kind) { 'S' => 1, 'M' => 2, 'L' => 3, default => 0 };","$message = match (true) { $score >= 80 => 'Great', $score >= 50 => 'Pass', default => 'Retry' };","How does match compare values?","Strictly, without fall-through","Loosely and always falling through","Only by string length","match uses strict matching and returns a result."],
    ["php-loops","Repeating Work with Loops","Use for, while, and foreach for different iteration patterns.","Choose foreach for collections, for when a counter is useful, and while when repetition depends on a condition. Ensure loop state changes so the loop can finish.","foreach ($names as $name) { echo $name; }","for ($i = 0; $i < 3; $i++) { echo $i; }","while ($remaining > 0) { $remaining--; }","Which loop is usually clearest for an array?","foreach","switch","try","foreach directly iterates over collection values."],
    ["php-functions","Defining Reusable Functions","Group logic into named units with parameters and return types.","Functions make behavior reusable and testable. Type declarations communicate expected inputs and outputs; return a value rather than relying on hidden global state.","function double(int $n): int { return $n * 2; }","function fullName(string $first, string $last): string { return \"$first $last\"; }","$result = double(6);","What does a return type describe?","The kind of value the function returns","The number of files in the project","The server's timezone","Return types declare expected output values."],
    ["php-arrays","Indexed and Associative Arrays","Store ordered values or values addressed by named keys.","PHP arrays can act as lists or key-value maps. Use [] to append, preserve meaningful keys when needed, and check that a key exists before reading optional data.","$colors = ['blue', 'green'];","$user = ['name' => 'Mina', 'active' => true];","$colors[] = 'orange';","How do you access an associative array value?","By its key","By a CSS selector","By its memory address","Associative arrays map keys to values."],
    ["php-superglobals","Reading Request and Environment Data","Know the global arrays PHP provides for requests and runtime settings.","Superglobals include $_GET, $_POST, $_FILES, $_COOKIE, $_SESSION, and $_SERVER. Treat request values as untrusted, check that expected keys exist, and avoid exposing server details.","$term = $_GET['q'] ?? '';","$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';","$uploaded = $_FILES['avatar'] ?? null;","Are values in $_GET trusted automatically?","No, validate them as untrusted input","Yes, the browser guarantees them","Only numeric values are trusted","Clients can send arbitrary request values."],
    ["php-regex","Pattern Matching with Regular Expressions","Describe text patterns for validation or extraction.","Regular expressions are useful for structured text patterns, but they can be harder to read than simple string functions. Anchor patterns when validating an entire value and use appropriate Unicode behavior when needed.","preg_match('/^PHP$/', $text);","preg_match('/^[A-Z]{2}[0-9]{4}$/', $code);","preg_match('/\bcat\b/i', $sentence);","What do anchors ^ and $ commonly represent?","The start and end of a string","A database table and column","A loop start and stop","Anchors can require a pattern to match the whole value."],
    ["php-regex-functions","Using PHP Regex Functions","Match, replace, or split text using PCRE helpers.","preg_match checks a pattern, preg_replace transforms matches, and preg_split divides text. Check return values and avoid using regular expressions as a substitute for a real parser for complex formats.","preg_match('/^[0-9]+$/', $value);","preg_replace('/\s+/', ' ', $text);","preg_split('/[,;]+/', $input);","Which function replaces matched text?","preg_replace","preg_match","preg_split","preg_replace performs pattern-based replacement."],
  ]),
  ...phpChapter("Forms and Validation", [
    ["php-form-handling","Handling Form Submissions","Read submitted fields and respond based on the request method.","Forms commonly submit with GET or POST. Check the method, read fields with safe defaults, and validate server-side because client-side controls can be bypassed.","$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';","$email = trim($_POST['email'] ?? '');","if ($method === 'POST') { /* validate and process */ }","Where should important form validation happen?","On the server","Only in browser JavaScript","Only in the HTML placeholder","Server checks cannot be skipped by changing browser code."],
    ["php-form-validation","Validating Form Values","Check submitted data against the rules your application requires.","Validation asks whether input is acceptable; sanitization or encoding serves other goals. Return clear errors and avoid trusting hidden fields for permissions or prices.","$age = filter_input(INPUT_POST, 'age', FILTER_VALIDATE_INT);","$name = trim($_POST['name'] ?? '');","if ($age === false || $age < 13) { $errors[] = 'Check age'; }","What does validation determine?","Whether data satisfies expected rules","Whether text should be displayed as HTML","Which stylesheet is active","Validation checks input against application requirements."],
    ["php-form-required","Requiring Form Fields","Reject missing or empty values on the server.","An HTML required attribute improves the form experience, but the server must also enforce required values. Trim text fields and distinguish an empty string from a valid value such as zero.","$name = trim($_POST['name'] ?? '');","if ($name === '') { $errors[] = 'Name is required'; }","$count = filter_input(INPUT_POST, 'count', FILTER_VALIDATE_INT);","Is an HTML required attribute enough by itself?","No, validate the submission on the server too","Yes, requests cannot bypass it","It encrypts the submitted value","Clients can send requests without the browser's form checks."],
    ["php-form-email-url","Validating Email and URL Fields","Use built-in filters for common address formats.","FILTER_VALIDATE_EMAIL and FILTER_VALIDATE_URL can check basic syntax. Successful validation does not prove the address exists or that a remote site is safe; apply policy checks appropriate to the feature.","$email = filter_var($rawEmail, FILTER_VALIDATE_EMAIL);","$url = filter_var($rawUrl, FILTER_VALIDATE_URL);","if ($email === false) { $errors[] = 'Enter a valid email'; }","Does email format validation prove that a mailbox exists?","No, it checks syntax only","Yes, it sends a confirmation automatically","It checks a user's password","Format validation does not verify ownership or delivery."],
    ["php-form-complete","Putting Form Handling Together","Combine validation, error display, and safe output.","A complete handler checks request method, validates every field, preserves safe form values, and processes data only after validation passes. Escape values when rendering them back into HTML.","$name = trim($_POST['name'] ?? '');","$email = filter_var($_POST['email'] ?? '', FILTER_VALIDATE_EMAIL);","if ($name !== '' && $email !== false) { echo 'Ready to save'; }","When should a valid form be processed?","After server-side validation succeeds","Before checking any fields","Only after echoing raw input","Processing follows successful validation."],
  ]),
];

phpLessons.push(...phpChapter("PHP Advanced Features", [
  ["php-datetime","Dates and Times","Create, format, and compare dates with timezone awareness.","DateTimeImmutable represents a date value without mutating it. Set or use explicit timezones for application logic and avoid assuming the server's local timezone matches the user.","$now = new DateTimeImmutable('now', new DateTimeZone('UTC'));","echo $now->format('Y-m-d H:i:s');","$nextWeek = $now->modify('+7 days');","Why prefer explicit timezone handling?","Server and user timezones may differ","It makes strings into arrays","It disables daylight saving","Explicit timezone rules avoid incorrect date assumptions."],
  ["php-include","Including Reusable PHP Files","Share templates and functions across PHP files.","include and require load another file; their once variants prevent repeated inclusion. Use a trusted fixed path, and prefer require for essential files so a missing dependency stops execution.","require __DIR__ . '/bootstrap.php';","include __DIR__ . '/partials/header.php';","require_once __DIR__ . '/lib/database.php';","Which form stops with an error if the file is missing?","require","include","echo","require is intended for dependencies the program cannot continue without."],
  ["php-file-handling","Working with Files","Read or write files with controlled paths and permissions.","File functions operate on server storage, so never use arbitrary request input directly as a path. Validate names, restrict operations to an intended directory, and handle failures.","$text = file_get_contents(__DIR__ . '/data.txt');","file_put_contents(__DIR__ . '/log.txt', \"opened\\n\", FILE_APPEND);","if (is_file($path) && is_readable($path)) { $text = file_get_contents($path); }","Why should paths from a request be restricted?","To prevent access to unintended server files","To make output colorful","To rename PHP variables","Untrusted paths can expose or overwrite data."],
  ["php-file-read","Opening and Reading Files","Choose a read mode and close file handles reliably.","fopen returns a handle or failure; fgets and fread can read from that handle. Close it after use, or use higher-level functions for simple whole-file reads.","$handle = fopen(__DIR__ . '/notes.txt', 'r');","$line = fgets($handle);","fclose($handle);","What does fopen with mode r request?","Read access to an existing file","Creation of a new directory","Deletion of the file","The r mode opens a file for reading."],
  ["php-file-write","Creating and Writing Files","Write data while handling permission and overwrite behavior.","Write modes can truncate existing content or append to it. Check the destination and result, use a controlled directory, and avoid writing attacker-controlled content into executable locations.","file_put_contents($path, 'First line');","file_put_contents($path, \"Next line\\n\", FILE_APPEND);","$bytes = file_put_contents($path, $content, LOCK_EX);","Which flag appends instead of replacing existing text?","FILE_APPEND","FILTER_VALIDATE_EMAIL","SORT_ASC","FILE_APPEND keeps previous content and adds new data."],
  ["php-file-upload","Handling File Uploads Safely","Validate uploaded files before storing them outside public execution paths.","Check the upload error, size, and actual file type on the server. Generate a safe random filename, move the temporary upload to a controlled directory, and never trust the submitted name or browser-provided MIME type alone.","if ($_FILES['file']['error'] === UPLOAD_ERR_OK) { /* continue checks */ }","$type = (new finfo(FILEINFO_MIME_TYPE))->file($_FILES['file']['tmp_name']);","move_uploaded_file($_FILES['file']['tmp_name'], $safeDestination);","Which upload detail should be trusted least?","The client-provided filename and MIME label","A server-side size check","The upload error code","Client-provided metadata can be forged."],
  ["php-cookies","Using Cookies","Store small client-held values with appropriate security flags.","Cookies are sent by the browser on later requests. Do not store secrets or sensitive personal information in plain cookies; set Secure, HttpOnly, and SameSite where appropriate and validate cookie contents.","setcookie('theme', 'light', ['httponly' => true, 'samesite' => 'Lax']);","$theme = $_COOKIE['theme'] ?? 'system';","setcookie('session_hint', '', ['expires' => time() - 3600, 'path' => '/']);","Why should sensitive data not be placed in a plain cookie?","The client can inspect and modify cookie data","Cookies exist only on the server","Cookies cannot be sent on requests","Cookie contents are stored on and sent by the browser."],
  ["php-sessions","Remembering Data with Sessions","Keep server-side state associated with a session identifier.","Sessions typically store data on the server and use a browser cookie to identify the session. Start sessions before output, regenerate identifiers after sign-in, and avoid placing secrets in client-readable data.","session_start();","$_SESSION['user_id'] = $userId;","session_regenerate_id(true);","What does the browser usually hold for a PHP session?","A session identifier cookie","The full server-side session data","The database password","The identifier connects requests to server-side session state."],
  ["php-filters","Filtering and Validating Values","Use filters to check common input types and formats.","Filters can validate values such as integers and email addresses, or sanitize selected representations. Understand each filter's behavior and still enforce application-specific limits.","filter_var($email, FILTER_VALIDATE_EMAIL);","filter_var($age, FILTER_VALIDATE_INT);","filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT);","What does a validate filter return on invalid input?","A failure value such as false","The original trusted value always","A database connection","Validation filters signal whether a value passed their rule."],
  ["php-filters-advanced","Combining Filters with Options","Apply filter options and validate structured input carefully.","Filter options can set numeric ranges and flags. Treat validation as one layer: also check business rules, authorization, and context-specific output encoding.","filter_var($age, FILTER_VALIDATE_INT, ['options' => ['min_range' => 13, 'max_range' => 120]]);","filter_var($url, FILTER_VALIDATE_URL);","filter_var($text, FILTER_UNSAFE_RAW);","What can min_range and max_range enforce?","An allowed numeric interval","A database table name","A file permission mode","Range options constrain validated numeric input."],
  ["php-callbacks","Callback Functions","Pass a function as a value to customize reusable operations.","A callback is a callable value supplied to another function. Closures and named functions can be used; keep callbacks focused and predictable, especially when processing user data.","$double = fn(int $n): int => $n * 2;","$values = array_map($double, [1, 2, 3]);","usort($names, fn($a, $b) => $a <=> $b);","What is a callback?","A function passed for another operation to call","A global variable","A file extension","Callbacks let an operation invoke supplied behavior."],
  ["php-json","Encoding and Decoding JSON","Exchange structured data with JSON using checked conversions.","json_encode turns PHP values into JSON and json_decode parses JSON. Handle encoding errors and decode untrusted input carefully; JSON is a data format, not a place to execute code.","$json = json_encode(['ok' => true], JSON_THROW_ON_ERROR);","$data = json_decode($json, true, 512, JSON_THROW_ON_ERROR);","header('Content-Type: application/json'); echo json_encode(['count' => 3]);","What does json_decode do?","Parses JSON text into PHP values","Creates a database table","Escapes HTML automatically","JSON decoding converts structured JSON text to PHP data."],
  ["php-exceptions","Handling Exceptions","Raise and catch exceptional conditions without hiding failures.","Exceptions represent failures that interrupt normal flow. Catch only errors you can handle, log useful context without revealing secrets, and use finally for cleanup that must always happen.","try { $result = riskyOperation(); } catch (RuntimeException $e) { /* handle */ }","throw new InvalidArgumentException('Invalid range');","try { work(); } finally { closeResource(); }","What is finally used for?","Cleanup that should run whether an exception occurs or not","A branch that runs only on success","A way to ignore every error","finally supports reliable cleanup."],
]));

phpLessons.push(...phpChapter("Object-Oriented PHP", [
  ["php-oop","Object-Oriented Programming","Model related data and behavior with objects.","Object-oriented programming groups state and operations into classes and objects. Use it where it clarifies a domain; small scripts can remain simpler with functions.","class Lamp { public function turnOn(): string { return 'On'; } }","$lamp = new Lamp(); echo $lamp->turnOn();","interface Payable { public function total(): int; }","What does an object combine?","State and behavior","Only comments and constants","A database server","Objects can package related data and operations."],
  ["php-classes-objects","Defining Classes and Creating Objects","Describe a type once and create individual instances.","A class declares properties and methods. An object is an instance with its own state; use the arrow operator to access instance members.","class Book { public string $title; }","$book = new Book(); $book->title = 'River';","class Counter { public function value(): int { return 0; } }","What is an instance of a class called?","An object","A namespace","A trait","An object is a created instance of a class."],
  ["php-constructor","Initializing Objects with Constructors","Set required object state when an instance is created.","The constructor runs when an object is instantiated. Constructor property promotion can declare and initialize properties compactly; validate important invariants during construction.","class User { public function __construct(public string $name) {} }","$user = new User('Mina');","class Range { public function __construct(public int $min, public int $max) { if ($min > $max) throw new InvalidArgumentException(); } }","When does a constructor run?","When an object is created","After every property read","When PHP exits","The constructor initializes the new instance."],
  ["php-destructor","Understanding Destructors","Know when an object's cleanup method may run.","A destructor is called when an object is being destroyed, but timing can depend on references and shutdown. Prefer explicit resource management or try/finally for critical cleanup rather than relying on shutdown timing.","class Temp { public function __destruct() { /* cleanup */ } }","$temp = new Temp(); unset($temp);","try { $handle = fopen($path, 'r'); } finally { if (isset($handle) && $handle) fclose($handle); }","Should critical cleanup rely only on destructor timing?","No, use predictable explicit cleanup where needed","Yes, destructors always run immediately","Destructors replace validation","Reference lifetime can affect when a destructor runs."],
  ["php-access-modifiers","Controlling Member Visibility","Use public, protected, and private to define class boundaries.","Public members are available from outside; protected members are available in the class and subclasses; private members belong to the declaring class. Expose only what callers need.","class Box { public string $label; }","class Base { protected int $count = 0; }","class Secret { private string $token = ''; }","Which modifier limits access to the declaring class?","private","public","protected","private restricts member access to its declaring class."],
  ["php-inheritance","Extending a Class","Reuse or specialize behavior through a parent-child relationship.","A child class can extend a parent and override methods. Use inheritance for a genuine subtype relationship; composition is often clearer when one object merely uses another.","class Animal { public function move(): string { return 'moves'; } }","class Bird extends Animal { public function fly(): string { return 'flies'; } }","$bird = new Bird(); echo $bird->move();","Which keyword creates a child class?","extends","implements","include","extends declares inheritance from a parent class."],
  ["php-class-constants","Class Constants","Attach fixed named values to a class.","Class constants belong to a class rather than one object. They are useful for stable domain values; use enums for richer finite state models when suitable.","class Status { public const OPEN = 'open'; }","echo Status::OPEN;","class Limits { private const MAX = 50; }","How do you access a class constant?","With the class name and ::","With an object arrow only","With $_GET","The scope resolution operator accesses class constants."],
  ["php-abstract-classes","Sharing a Partial Class Contract","Use an abstract base class when subclasses must provide specific behavior.","An abstract class cannot be instantiated directly and may declare abstract methods for children to implement. It can also provide shared concrete behavior.","abstract class Shape { abstract public function area(): float; }","class Square extends Shape { public function __construct(private float $side) {} public function area(): float { return $this->side ** 2; } }","$shape = new Square(3);","Can you instantiate an abstract class directly?","No","Yes, with new","Only if it has no methods","Abstract classes are incomplete base types."],
  ["php-interfaces","Defining Interfaces","Specify methods that implementing classes agree to provide.","An interface describes a public contract without defining ordinary instance state. A class can implement multiple interfaces, making capabilities explicit across unrelated classes.","interface Logger { public function log(string $message): void; }","class FileLogger implements Logger { public function log(string $message): void {} }","function record(Logger $logger): void { $logger->log('saved'); }","What does an interface define?","A contract for implementing classes","A database connection by itself","A global variable","Interfaces specify required public behavior."],
  ["php-traits","Reusing Methods with Traits","Share method implementations across classes where inheritance is not appropriate.","Traits insert reusable methods into a class. Keep traits cohesive and watch for naming conflicts; traits do not create a substitute for a clear object model.","trait HasTimestamp { public function now(): DateTimeImmutable { return new DateTimeImmutable(); } }","class Event { use HasTimestamp; }","class Job { use HasTimestamp; }","What do traits help share?","Method implementations across classes","A parent database","Only class constants","Traits provide reusable behavior without a parent-child relation."],
  ["php-static-methods","Static Methods","Call behavior on a class when it does not need object state.","Static methods are called with :: and do not have an instance $this. Prefer instance methods for behavior that depends on an object's state; avoid turning every helper into global-like static state.","class Slug { public static function make(string $s): string { return strtolower($s); } }","$slug = Slug::make('PHP');","class MathUtil { public static function twice(int $x): int { return $x * 2; } }","Can a static method use $this?","No, it has no current instance","Yes, always","Only in a trait","Static methods have no object instance context."],
  ["php-static-properties","Static Properties","Store class-level state shared by class access.","A static property belongs to the class rather than to each instance. Shared mutable state can make programs harder to reason about; use it intentionally and keep state lifetimes clear.","class VisitCounter { public static int $count = 0; }","VisitCounter::$count++;","echo VisitCounter::$count;","Where does a static property belong?","To the class","To each HTML form","To a single function call","Static properties are shared at class level."],
  ["php-namespaces","Organizing Names with Namespaces","Avoid naming collisions by grouping classes and functions.","Namespaces provide a naming scope for PHP declarations. Composer's autoloader commonly maps namespaces to files, so use consistent names and imports in larger projects.","namespace App\\Models;","use App\\Services\\Mailer;","$service = new Mailer();","What problem do namespaces help reduce?","Name collisions","SQL injection by themselves","Slow network speed","Namespaces separate identifiers from other code."],
  ["php-iterables","Working with Iterables","Write functions that accept arrays or iterable objects.","iterable is a type that accepts arrays and Traversable objects. Generators can produce values on demand, which is useful for processing larger sequences without building a full array first.","function show(iterable $items): void { foreach ($items as $item) echo $item; }","function ids(): Generator { yield 1; yield 2; }","foreach (ids() as $id) { echo $id; }","What can iterable accept?","Arrays and Traversable values","Only strings","Only database tables","Iterable supports arrays and Traversable implementations."],
]));

phpLessons.push(...phpChapter("PHP and MySQL", [
  ["php-mysql-overview","Connecting PHP to a Database","Separate connection setup from queries and handle failures safely.","PHP can connect through PDO or a database-specific driver such as MySQLi. Keep connection secrets in environment configuration, use least-privilege accounts, and report errors without exposing credentials.","$pdo = new PDO($dsn, $user, $password);","$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);","$mysqli = new mysqli($host, $user, $password, $database);","Where should production database passwords live?","In protected environment configuration","In public source code","In a URL query parameter","Secrets should not be committed or exposed to users."],
  ["php-mysql-connect","Establishing a MySQL Connection","Create a database connection and detect connection problems.","Choose PDO or MySQLi consistently. Configure character encoding, exception behavior, and timeouts deliberately; never display raw connection errors to visitors.","$pdo = new PDO($dsn, $user, $password);","$mysqli = new mysqli($host, $user, $password, $database);","$pdo->exec(\"SET NAMES utf8mb4\");","What should an app do with raw connection errors in production?","Log safely and show a general error","Print the password and stack trace","Ignore all failures","Detailed errors can reveal sensitive configuration."],
  ["php-mysql-create-database","Creating a MySQL Database","Understand database creation as a privileged setup task.","Database creation is usually handled by an administrator or deployment migration. Applications should normally connect to an already-created database with only the permissions they need.","CREATE DATABASE learning_app CHARACTER SET utf8mb4;","CREATE DATABASE IF NOT EXISTS learning_app;","SHOW DATABASES;","Who should normally create production databases?","A controlled setup or migration process","Every public page request","An unvalidated form field","Database creation requires controlled privileges."],
  ["php-mysql-create-table","Creating Tables for PHP Data","Define columns, primary keys, and constraints before inserting rows.","A table schema captures data types and integrity rules. Use a primary key and appropriate constraints, and create or update schemas through reviewed migrations.","CREATE TABLE members (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL);","CREATE TABLE posts (id INT PRIMARY KEY, title VARCHAR(200) NOT NULL);","CREATE TABLE enrollments (member_id INT, course_id INT, PRIMARY KEY(member_id,course_id));","Why define constraints in a table?","To protect data integrity","To style a form","To render PHP tags","Constraints apply rules at the database layer."],
  ["php-mysql-insert","Inserting a Database Row","Add one row using placeholders for values.","Prepared statements separate SQL structure from input values. Validate application rules first and bind each value using the driver; do not concatenate form input into SQL.","$stmt = $pdo->prepare('INSERT INTO members (name) VALUES (:name)');","$stmt->execute(['name' => $name]);","$stmt = $mysqli->prepare('INSERT INTO members (name) VALUES (?)');","Why use a prepared statement for form values?","It binds data separately from SQL syntax","It encrypts the whole database automatically","It replaces server-side validation","Bound parameters reduce injection risk."],
  ["php-mysql-last-id","Reading the Last Inserted ID","Get the identifier created by a successful insert.","PDO::lastInsertId or MySQLi insert_id can report the generated ID for the current connection. Read it after the insert and do not guess IDs by querying a maximum value.","$id = $pdo->lastInsertId();","$id = $mysqli->insert_id;","echo (int) $id;","Why not use SELECT MAX(id) as the inserted row ID?","Another request may insert a row between operations","MAX always returns the current user's row","IDs are sorted by name","Connection-scoped last-ID methods avoid a race-prone guess."],
  ["php-mysql-multiple-insert","Inserting Multiple Rows","Use repeated prepared executions or a controlled batch insert.","For several rows, reuse a prepared statement or a transaction. Validate the complete input and use transactions when all rows should succeed or fail together.","$stmt = $pdo->prepare('INSERT INTO tags (label) VALUES (?)');","foreach ($labels as $label) { $stmt->execute([$label]); }","$pdo->beginTransaction(); $pdo->commit();","When is a transaction useful for a batch?","When the batch should be atomic","When each row must use a different database","When PHP should skip validation","Transactions group related operations into one unit."],
  ["php-mysql-prepared","Prepared Queries with PDO and MySQLi","Bind user data rather than building query strings.","PDO and MySQLi support prepared statements. Placeholders represent values, not identifiers; for dynamic column names, select from a fixed allowlist and quote according to the chosen database.","$stmt = $pdo->prepare('SELECT * FROM members WHERE id = ?');","$stmt->execute([$id]);","$stmt = $mysqli->prepare('SELECT name FROM members WHERE id = ?');","Can a placeholder safely stand for a table name?","No, placeholders bind values","Yes, for any SQL keyword","Only inside INSERT","Identifiers need controlled allowlisting, not value binding."],
  ["php-mysql-select","Selecting Rows from MySQL","Fetch query results and choose an appropriate fetch mode.","A SELECT query retrieves rows; PDO can fetch associative arrays for named column access. Limit returned columns and rows to what the page needs.","$stmt = $pdo->query('SELECT id, name FROM members');","$rows = $stmt->fetchAll(PDO::FETCH_ASSOC);","foreach ($rows as $row) { echo htmlspecialchars($row['name'], ENT_QUOTES, 'UTF-8'); }","Why select only needed columns?","To reduce unnecessary data transfer and exposure","To make SQL ignore permissions","To automatically validate output","Selecting specific columns keeps results focused."],
  ["php-mysql-where","Filtering Database Rows","Use conditions and parameters to retrieve matching records.","WHERE limits which rows a query returns or changes. Bind values, use indexes that fit common filters, and be especially careful with UPDATE and DELETE conditions.","$stmt = $pdo->prepare('SELECT id FROM members WHERE email = ?');","$stmt->execute([$email]);","SELECT id FROM posts WHERE published = 1;","What does WHERE do in SELECT?","Filters rows by a condition","Creates a new column","Sorts the result","WHERE selects records that satisfy the condition."],
  ["php-mysql-order","Sorting Database Results","Use ORDER BY with a stable tie-breaker for predictable pages.","ORDER BY specifies result order. Add a unique secondary key when sort values can repeat, and use a fixed allowlist if a user can choose a sort field.","SELECT id, name FROM members ORDER BY name ASC;","SELECT id, created_at FROM posts ORDER BY created_at DESC, id DESC;","SELECT id FROM products ORDER BY price ASC;","How can ordering remain stable when values tie?","Add a unique tie-breaker column","Remove ORDER BY","Sort in a hidden form field","A tie-breaker establishes deterministic order."],
  ["php-mysql-delete","Deleting Database Rows","Delete only intended rows and verify the target condition.","DELETE permanently removes matching rows unless a transaction or backup allows recovery. Preview with SELECT using the same WHERE condition and bind user values.","SELECT id FROM members WHERE id = ?;","$stmt = $pdo->prepare('DELETE FROM members WHERE id = ?');","$stmt->execute([$id]);","What should happen before a risky DELETE?","Preview the target rows with the same condition","Remove WHERE to be safe","Trust the submitted ID","Previewing confirms the target set."],
  ["php-mysql-update","Updating Database Rows","Change selected columns on rows matched by a condition.","UPDATE without a correct WHERE may change every row. Bind values, preview targets, and use a transaction for changes that need review or rollback.","$stmt = $pdo->prepare('UPDATE members SET name = ? WHERE id = ?');","$stmt->execute([$name, $id]);","UPDATE inventory SET quantity = quantity - 1 WHERE sku = 'A12';","What is the risk of omitting WHERE from an update?","Every row may be changed","The query changes no rows","Only indexes are changed","An update without a filter applies to the whole table."],
  ["php-mysql-limit","Limiting Database Results","Return a bounded result set for lists and pagination.","LIMIT bounds rows in MySQL. Use an explicit order for meaningful pages and validate numeric limits; syntax for row limits and placeholders may differ across database drivers.","SELECT id, name FROM members ORDER BY id LIMIT 20;","SELECT id FROM posts ORDER BY created_at DESC LIMIT 10 OFFSET 20;","$limit = max(1, min(50, (int) $requested));","Why combine LIMIT with ORDER BY?","To make the returned subset predictable","To create an index automatically","To validate an email","Ordering determines which rows appear in the limited subset."],
]));

phpLessons.push(...phpChapter("XML with PHP", [
  ["php-xml-overview","Working with XML","Understand XML structure and parsing choices.","XML represents nested data using elements and attributes. Choose a parser based on document size and access patterns, and treat external XML as untrusted input.","$xml = '<catalog><item id=\"1\">Book</item></catalog>';","$root = simplexml_load_string($xml);","$dom = new DOMDocument(); $dom->loadXML($xml, LIBXML_NONET);","What is XML structured from?","Nested elements and attributes","Only SQL rows","CSS declarations","XML describes structured data with nested markup."],
  ["php-xml-parsers","Choosing an XML Parser","Match a parser to the document and memory constraints.","Tree parsers load document structures for convenient navigation; event parsers process pieces as they arrive. Disable network access for untrusted input and check parser errors.","simplexml_load_file($path);","$reader = new XMLReader();","$dom = new DOMDocument();","When might an event or streaming parser help?","When processing a large document incrementally","When styling a button","When validating a password hash","Streaming avoids loading the entire document tree at once."],
  ["php-simplexml","Parsing XML with SimpleXML","Load a manageable XML document into an easy-to-navigate object.","SimpleXML is convenient for ordinary XML documents. Check that parsing succeeded and use libxml error handling when you need useful diagnostics.","$xml = simplexml_load_string($source);","if ($xml === false) { echo 'Invalid XML'; }","foreach ($xml->item as $item) { echo (string) $item; }","What is SimpleXML useful for?","Convenient access to XML elements","Executing JavaScript","Creating SQL indexes","SimpleXML offers a lightweight tree-like interface."],
  ["php-simplexml-get","Reading XML Elements and Attributes","Navigate nodes and attributes from a parsed XML object.","SimpleXML exposes child elements as properties and attributes through array-like access. Cast values to strings or numbers deliberately and handle missing nodes.","$title = (string) $xml->book->title;","$id = (string) $xml->book['id'];","foreach ($xml->book as $book) { echo (string) $book->title; }","How can an attribute be accessed?","Through the node's attribute key","With $_SESSION","Using a CSS class","SimpleXML exposes XML attributes from their element."],
  ["php-expat","Event Parsing with Expat","Process XML as parser events instead of building a full document tree.","Expat-style parsing invokes callbacks for start tags, text, and end tags. It suits stream-like processing, but the application must maintain state as events arrive.","$parser = xml_parser_create();","xml_set_element_handler($parser, $start, $end);","xml_parse($parser, $chunk, $isFinal);","What does an event parser call during parsing?","Handlers for elements and text events","CSS selectors only","Database triggers","Callbacks let code process pieces of the XML stream."],
  ["php-dom","Editing XML with DOM","Navigate and modify XML through a document tree.","DOMDocument represents a document as nodes that can be queried or changed. Load untrusted XML with network access disabled, check errors, and serialize only the intended document.","$dom = new DOMDocument();","$dom->loadXML($source, LIBXML_NONET);","$dom->getElementsByTagName('title')->item(0)?->nodeValue;","What does DOM provide?","A node-based document tree","A PHP session store","An HTTP router","DOM exposes document nodes for navigation and editing."],
]));

phpLessons.push(...phpChapter("AJAX with PHP", [
  ["php-ajax-intro","AJAX and Asynchronous Requests","Update part of a page by requesting data in the background.","AJAX describes browser requests that happen without a full page navigation. Modern code commonly uses fetch; the server returns data, often JSON, which the page then renders safely.","fetch('/api/items').then(r => r.json()).then(showItems);","fetch('/api/search?q=' + encodeURIComponent(term));","fetch('/api/status').then(response => response.ok);","What does an asynchronous request allow?","A page to request data without a full navigation","PHP to run inside CSS","A database to draw buttons","The browser can update a page after a background response."],
  ["php-ajax-endpoint","Returning JSON from PHP","Build a small endpoint that responds with structured data.","A PHP endpoint should validate request values, set the JSON content type, and return a predictable response shape. Avoid echoing debug output before the JSON body.","header('Content-Type: application/json');","echo json_encode(['ok' => true], JSON_THROW_ON_ERROR);","http_response_code(400); echo json_encode(['error' => 'Bad input']);","Why set the JSON content type?","It tells the client how to interpret the response","It encrypts the response","It validates the database","The header describes the response format."],
  ["php-ajax-database","Loading Database Results Asynchronously","Combine a validated request, parameterized query, and JSON response.","An endpoint that reads a database should bind request values, limit result sizes, and return only fields the client needs. The browser must still treat returned text as data and render it safely.","$stmt = $pdo->prepare('SELECT id,title FROM posts WHERE category = ? LIMIT 20');","$stmt->execute([$category]);","echo json_encode($stmt->fetchAll(PDO::FETCH_ASSOC), JSON_THROW_ON_ERROR);","How should request values enter a database query?","Through bound parameters","By concatenating into SQL","As a PHP comment","Bound parameters keep request data separate from SQL code."],
  ["php-ajax-xml","Requesting XML Asynchronously","Fetch XML data and parse it in a controlled way.","A browser can request XML and parse the response as a document. Prefer JSON for many new application APIs, but XML remains useful when an existing system uses it.","fetch('/feed.xml').then(r => r.text());","const doc = new DOMParser().parseFromString(text, 'application/xml');","doc.querySelector('item title')?.textContent;","What should client code do after receiving XML text?","Parse it as XML before querying nodes","Run it as PHP","Concatenate it into SQL","Parsing creates a document tree the client can inspect."],
  ["php-ajax-live-search","Building a Live Search","Send validated search terms and render matching results.","Live search sends a term after user input, often with a short debounce. The PHP endpoint should use a parameterized LIKE query, cap results, and the browser should insert result text safely.","const params = new URLSearchParams({ q: term });","fetch('/search.php?' + params).then(r => r.json());","const row = document.createTextNode(result.title);","Why debounce a live search field?","To avoid sending a request for every rapid keystroke","To encrypt SQL automatically","To make results alphabetical","Debouncing reduces unnecessary requests during typing."],
  ["php-ajax-polling","Polling for Updates","Check periodically for new data when a push channel is not being used.","Polling repeats a request on a timer. Use a sensible interval, stop polling when the page is inactive, and return only changes or a compact status to limit work.","const timer = setInterval(checkStatus, 10000);","clearInterval(timer);","fetch('/status.php').then(r => r.json());","What is polling?","Repeating a request at intervals","Opening a database transaction","Sending a file upload","Polling checks for updates repeatedly over time."],
]));

phpLessons.push(...phpChapter("PHP Reference and Practice", [
  ["php-reference-overview","PHP Language Overview","Use a topic map to connect language syntax, runtime, and common libraries.","PHP includes language constructs, standard functions, extensions, and runtime configuration. Check the installed runtime and enabled extensions when code behaves differently between development and hosting.","php -v","php -m","php --ini","What can php -m show?","Loaded extensions","Git branches","The browser's cookies","Extensions provide additional runtime capabilities."],
  ["php-reference-arrays-strings","Array and String Tools","Choose standard functions for collection and text tasks.","Array helpers include count, array_map, array_filter, and sort; string helpers include trim, strlen, str_contains, and explode. Check whether a function mutates input or returns a new value.","$parts = explode(',', $line);","$clean = trim($text);","$names = array_map('strtoupper', $names);","What does trim commonly remove?","Whitespace from the ends of a string","Duplicate database rows","A PHP class","trim removes whitespace at the string boundaries by default."],
  ["php-reference-date-time","Date, Calendar, and Timezone Tools","Format and calculate dates with explicit timezone rules.","DateTimeImmutable and DateTimeZone help represent and transform dates. Convert to the user's preferred timezone for display, while storing timestamps consistently for comparison.","$zone = new DateTimeZone('UTC');","$date = new DateTimeImmutable('2026-05-12', $zone);","echo $date->format('D, d M Y');","Which class represents a timezone?","DateTimeZone","DirectoryIterator","DOMNode","DateTimeZone names the rules used to interpret a date."],
  ["php-reference-filesystem-directory","Filesystem and Directory Tools","Inspect and manage files using controlled server paths.","Filesystem functions include file_exists, is_readable, mkdir, and directory iterators. Restrict paths to known directories and never expose server filesystem details to a public response.","is_file($path);","is_readable($path);","$files = scandir(__DIR__ . '/public-data');","What is a safe path-handling rule?","Keep operations inside an intended directory","Use raw user input as a path","Show absolute server paths to visitors","Restricting paths limits unintended file access."],
  ["php-reference-errors-exceptions","Errors and Exceptions","Distinguish diagnostics from recoverable application failures.","Configure error reporting for development and log failures safely in production. Catch exceptions at boundaries where the application can respond, but do not silently ignore errors.","error_reporting(E_ALL);","try { runTask(); } catch (Throwable $e) { error_log($e->getMessage()); }","http_response_code(500);","Why avoid showing detailed errors to every production visitor?","They may reveal internal paths or secrets","They make HTML tags uppercase","They slow down Git","Private diagnostics belong in protected logs."],
  ["php-reference-filters-validation","Filter and Validation Reference","Check common values and then enforce domain-specific rules.","Use appropriate validators for integers, email, and URLs; use application checks for ranges, ownership, and permissions. Validation is not the same as HTML escaping or SQL parameterization.","filter_var($email, FILTER_VALIDATE_EMAIL);","filter_var($page, FILTER_VALIDATE_INT);","filter_var($url, FILTER_VALIDATE_URL);","Does valid email syntax confirm account ownership?","No, use a confirmation process for ownership","Yes, always","Only when the address has a dot","Syntax checks cannot confirm who controls a mailbox."],
  ["php-reference-json-xml","JSON, XML, and Library Tools","Choose structured data parsers for the format you receive.","JSON tools encode and decode API data; XML tools include SimpleXML, XMLReader, and DOM. Handle parse failures and use safe parser options for untrusted documents.","json_encode($data, JSON_THROW_ON_ERROR);","simplexml_load_string($xml);","$reader = new XMLReader();","Which parser is suited to stream-like XML processing?","XMLReader","json_encode","mail","XMLReader can process XML incrementally."],
  ["php-reference-network-mail","Network and Email Operations","Treat outbound network and email features as controlled integrations.","Network functions and mail delivery depend on server configuration and deployment policy. Validate destinations, set timeouts, avoid sending secrets in URLs, and use a reliable mail service for production delivery.","$context = stream_context_create(['http' => ['timeout' => 5]]);","$response = file_get_contents($url, false, $context);","// Send mail through a configured mail transport","Why set a network timeout?","To prevent a request waiting forever","To change a PHP variable's type","To validate XML tags","Timeouts bound how long an external request can stall."],
  ["php-reference-output-buffering","Output and Buffer Control","Understand when output buffering is useful and avoid accidental response output.","Output buffering can capture or delay output, but headers must still be sent before body output. Use it intentionally for templates or response composition rather than hiding unwanted warnings.","ob_start();","echo '<main>Page</main>';","$html = ob_get_clean();","Why can early output cause header problems?","Headers must be sent before response body content","PHP only allows one echo","Output buffering disables sessions","HTTP headers precede body output in the response."],
  ["php-reference-regex-streams","Regular Expressions and Streams","Work with pattern matching and stream-based input deliberately.","PCRE functions handle text patterns; stream functions handle data sources such as files and network connections. Choose simpler string operations when sufficient, and set limits for untrusted or remote inputs.","preg_match('/^[A-Z]+$/', $code);","$stream = fopen($path, 'rb');","stream_get_contents($stream, 4096);","What is a stream useful for?","Reading data incrementally from a source","Defining a PHP class","Creating a browser cookie","Streams provide a common interface to data sources."],
  ["php-reference-mysqli","MySQLi Reference","Use MySQL-specific PHP APIs with prepared statements.","MySQLi is a PHP extension for MySQL. It offers procedural and object-oriented styles; use prepared statements for values, set the connection charset, and handle errors consistently.","$db = new mysqli($host, $user, $pass, $name);","$db->set_charset('utf8mb4');","$stmt = $db->prepare('SELECT id FROM members WHERE email = ?');","What database is MySQLi designed for?","MySQL","Every XML database","Only SQLite","MySQLi is a MySQL-specific interface."],
  ["php-reference-keywords-variables","Keywords and Variable Handling","Recognize reserved language words and inspect values safely.","Keywords have meaning in PHP syntax and should not be used as ordinary identifiers. Variable-handling utilities can inspect or unset variables, but avoid dynamic variable names when normal arrays are clearer.","isset($value);","unset($temporary);","$value = is_numeric($input) ? (float) $input : null;","What is a PHP keyword?","A reserved word with language meaning","A user-defined filename","An HTML color","Keywords are part of the language syntax."],
  ["php-reference-calendar-zip-ftp","Calendar, Archive, and Transfer Extensions","Check extension support before relying on specialized utilities.","Calendar calculations, ZIP archives, and FTP operations are provided through functions or extensions whose availability may vary by host. Confirm configuration and prefer secure transfer protocols for sensitive data.","$zip = new ZipArchive();","$weekday = cal_days_in_month(CAL_GREGORIAN, 5, 2026);","$ftp = ftp_connect($host, 21, 5);","Why check extension availability?","The server may not have that extension enabled","PHP installs every extension automatically","Extensions do not affect runtime behavior","Hosting configuration determines which extensions are available."],
  ["php-examples","PHP Example Patterns","Read small examples and adapt them to the request and data model.","Examples are starting points, not complete production systems. Add validation, error handling, authentication, and tests that fit the feature before using code with real data.","$items = ['pen', 'book'];","$prices = array_map(fn($n) => $n * 1.1, [10, 20]);","echo json_encode(['items' => count($items)]);","What should you do before using a small example in a real app?","Adapt it with suitable validation and error handling","Paste it without review","Use production credentials in the snippet","Examples need context and safe application rules."],
  ["php-compiler-terminal","Running PHP from a Terminal","Execute scripts and inspect errors in a local development environment.","The PHP CLI runs a script without serving it through a web server. Use it for quick experiments, maintenance tasks, and command-line tools; keep web request assumptions separate.","php --version","php script.php","php -l script.php","What does php -l check?","PHP syntax without executing the script","The remote Git history","HTML accessibility","Lint mode checks syntax."],
  ["php-code-challenges","PHP Code Challenges","Practice variables, branches, collections, and functions.","Start with a clear input and expected output, solve a small task, and test normal and boundary cases. Use strict types where helpful and explain assumptions in your solution.","$numbers = [3, 5, 8];","$even = array_filter($numbers, fn($n) => $n % 2 === 0);","echo array_sum($even);","What improves a code challenge solution?","Testing normal and boundary inputs","Using the shortest possible line","Ignoring the expected output","Boundary testing reveals assumptions and edge cases."],
  ["php-practice-problems","PHP Practice Problems","Build confidence by solving related tasks in increasing steps.","Progress from formatting strings and filtering arrays to processing validated forms and returning JSON. Save each solution, explain the reasoning, and revisit problems after learning new tools.","$words = ['php', 'forms', 'safe'];","$long = array_filter($words, fn($word) => strlen($word) > 3);","sort($long);","How should practice problems progress?","From simpler concepts toward combined tasks","From production deployments to syntax","By skipping review","Gradual challenges build concepts in layers."],
  ["php-server-basics","Understanding the PHP Web Server","Know how requests reach PHP and how responses return to browsers.","A web server routes a request to PHP, which executes code and sends headers and a body. Keep public assets separate from configuration and ensure errors are logged in a controlled place.","php -S localhost:8000","header('Content-Type: text/plain; charset=utf-8');","http_response_code(404);","What does PHP send back after processing a request?","An HTTP response","A Git commit","A CSS file automatically","The server returns a response containing headers and content."],
  ["php-syllabus-study-plan","PHP Syllabus and Study Plan","Follow a path from syntax through web forms, data, and projects.","A practical path covers values and control flow, functions and arrays, validation and output safety, files and sessions, object design, database access, and APIs. Build a small project to connect the topics.","// Step 1: values and conditions","// Step 2: functions and arrays","// Step 3: validated forms and prepared database queries","What helps connect topics into usable skill?","A small project that applies several concepts","Memorizing headings only","Skipping server-side checks","Projects make related language features work together."],
]));

phpLessons.push(...phpChapter("Assessment", [
  ["php-certificate-preparation","PHP Certificate Preparation","Review core concepts and prepare with practical self-checks.","A certificate review should test your ability to read code, trace values, write functions, validate a form, and handle database input safely. Use practice tasks to find gaps; a certificate itself is earned through the assessment provider.","$total = array_sum([4, 7, 9]);","$label = match ($status) { 'open' => 'Waiting', default => 'Other' };","$stmt = $pdo->prepare('SELECT id FROM members WHERE email = ?');","What makes a useful certificate preparation plan?","Practice core syntax and apply it in small programs","Memorize answers without writing code","Skip input validation topics","Applied practice checks understanding beyond memorized terms."],
  ["php-knowledge-quiz","PHP Knowledge Check","Review syntax, arrays, request data, objects, and safe database queries.","Use this lesson as a short recap before building a project. For every answer, explain why the other options are incorrect and run examples locally when possible.","$items = ['one', 'two']; echo count($items);","function greet(string $name): string { return \"Hi $name\"; }","$stmt = $pdo->prepare('SELECT * FROM users WHERE id = ?');","What should PHP do before using a value received from a request?","Validate it for the feature's rules","Assume the browser already checked it","Use it as a SQL fragment","Request data is controlled by the client and must be checked."],
]));
